import { Project } from "../../domain/project";
import type { ProjectRepository } from "../../domain/project-repository";
import { toProjectDto } from "../dto/project-dto";
import type { CreateProjectInput, ProjectDto } from "../dto/project-dto";
import { translateDomainErrors } from "../errors";

export class CreateProjectUseCase {
  constructor(private readonly projects: ProjectRepository) {}

  execute(input: CreateProjectInput): ProjectDto {
    const project = translateDomainErrors(() =>
      Project.create(this.projects.nextId(), input.name),
    );
    this.projects.save(project);
    return toProjectDto(project);
  }
}

